window.KanseiBooking={"naprapati":{"url":"https://www.bokadirekt.se/boka-tjanst/kansei-rehabcenter-48847/naprapati-ny-resp-aterbesok-3263299","label":"Boka naprapati","price":"890 kr"},"ultraljud":{"url":"https://www.bokadirekt.se/boka-tjanst/kansei-rehabcenter-48847/ultraljud-rorelseapparaten-1946824","label":"Boka ultraljud","price":"1 290 kr"},"akupunktur":{"url":"https://www.bokadirekt.se/boka-tjanst/kansei-rehabcenter-48847/naprapati-ny-resp-aterbesok-3263299","label":"Boka naprapati","price":"890 kr"},"rehabilitering":{"url":"https://www.bokadirekt.se/boka-tjanst/kansei-rehabcenter-48847/naprapati-ny-resp-aterbesok-3263299","label":"Boka rehabbesök","price":"890 kr"},"skuldra":{"url":"https://www.bokadirekt.se/boka-tjanst/kansei-rehabcenter-48847/axelbedomning-av-magnus-wennerlund-3318465","label":"Boka axelbedömning","price":"1 290 kr"},"prp":{"url":"https://www.bokadirekt.se/boka-tjanst/kansei-rehabcenter-48847/konsultation-infor-injektionsbehandling-3409513","label":"Boka konsultation","price":"890 kr"},"hyaluronsyra":{"url":"https://www.bokadirekt.se/boka-tjanst/kansei-rehabcenter-48847/konsultation-infor-injektionsbehandling-3409513","label":"Boka konsultation","price":"890 kr"},"kortison":{"url":"https://www.bokadirekt.se/boka-tjanst/kansei-rehabcenter-48847/konsultation-infor-injektionsbehandling-3409513","label":"Boka konsultation","price":"890 kr"},"injektioner":{"url":"https://www.bokadirekt.se/boka-tjanst/kansei-rehabcenter-48847/konsultation-infor-injektionsbehandling-3409513","label":"Boka konsultation","price":"890 kr"}};
/* Loaded only when someone asks for booking guidance. No diagnosis or health-data transmission. */
window.KanseiGuide = function(ctx) {
  'use strict';
  const {$,$$,escapeHTML,arrow,areas,prepareLinks,listen,guide,content,openDialog}=ctx;
  let state={area:null,pattern:null,screen:'areas',history:[]};
  const resetState=()=>{state={area:null,pattern:null,screen:'areas',history:[]};};
    const step=(label,n)=>`<div class="guide-progress"><span>${escapeHTML(label)}</span><span class="progress-track" aria-hidden="true">${[1,2,3].map(i=>`<i class="${i<=n?'active':''}"></i>`).join('')}</span></div>`;
    const heading=t=>`<h2 id="guide-title" tabindex="-1">${escapeHTML(t)}</h2>`;
    const choice=(attr,value,title,sub='')=>`<button class="guide-choice" type="button" ${attr}="${escapeHTML(value)}"><span><b>${escapeHTML(title)}</b>${sub?'<small>'+escapeHTML(sub)+'</small>':''}</span>${arrow}</button>`;
    const routeLink=(path,label,cls='text-link')=>`<a class="${cls}" href="${escapeHTML(path)}" data-route="${escapeHTML(path)}">${escapeHTML(label)} ${arrow}</a>`;
    const back=(label='Tillbaka')=>`<div class="guide-actions"><button class="guide-back" type="button" data-guide-back>← ${escapeHTML(label)}</button><button class="guide-back" type="button" data-reset>Börja om</button></div>`;
    const move=(screen)=>{state.history.push(state.screen);state.screen=screen;renderGuide();};
    function renderGuide(){
      if(!content)return;
      const area=areas[state.area],pattern=area?.patterns.find(p=>p[0]===state.pattern);
      if(state.screen==='areas'){
        content.innerHTML=step('01 / VAD SÖKER DU HJÄLP FÖR?',1)+heading('Vi hjälper dig att välja.')+'<p>Välj området som besvärar dig mest. Det här är bokningshjälp, inte en medicinsk bedömning.</p><div class="guide-choices">'+Object.entries(areas).map(([k,d])=>choice('data-guide-area',k,d.label)).join('')+'</div><div class="guide-actions"><button class="guide-back" type="button" data-guide-services>Jag söker en viss tjänst →</button><button class="guide-back" type="button" data-guide-care>Akuta besvär?</button></div>';
      }else if(state.screen==='patterns' && area){
        content.innerHTML=step('01 / '+area.label.toUpperCase(),1)+heading(area.question)+'<p>Välj det som ligger närmast. Du kan ändra ditt val.</p><div class="guide-choices">'+area.patterns.map(p=>choice('data-pattern',p[0],p[1],p[2])).join('')+choice('data-pattern','unclear','Svårt att beskriva','Jag vill börja med en bedömning.')+'</div>'+back('Välj ett annat område');
      }else if(state.screen==='safety'){
        content.innerHTML=step('02 / INNAN DU GÅR VIDARE',2)+heading('Behöver du sjukvård först?')+'<p>Kansei tar emot för planerade besök. Akuta eller snabbt försämrade besvär kan behöva bedömas av annan vård.</p><div class="safety-box"><strong>Stämmer något av detta?</strong><ul><li>Ny skada med mycket ont eller svårt att belasta.</li><li>En röd, varm eller svullen led tillsammans med feber eller sjukdomskänsla.</li><li>Ny eller snabbt ökande svaghet. Ryggsmärta med nedsatt känsel i underlivet eller problem att kontrollera urin eller avföring.</li></ul></div><div class="guide-choices">'+choice('data-safety','care','Ja, eller jag är osäker','Visa hur jag får hjälp att hitta rätt vård.')+choice('data-safety','continue','Nej, fortsätt till bokningshjälpen')+'</div><p class="guide-small">Detta är inte en fullständig säkerhetskontroll. Ett nej utesluter inte ett allvarligt tillstånd. Vid oro eller osäkerhet: kontakta 1177.</p>'+back('Till mina val');
      }else if(state.screen==='care'){
        content.innerHTML=step('KONTAKTA SJUKVÅRDEN',2)+heading('Börja inte med en vanlig bokning.')+'<p>Ny skada, tydliga varningssymtom eller osäkerhet om hur bråttom det är behöver bedömas av sjukvården. Webbplatsen kan inte avgöra vårdnivån åt dig.</p><div class="warning-box"><strong>Kontakta vården utan att vänta på en bokning här.</strong><br>Ring 1177 för vägledning. Vid tecken på ett livshotande tillstånd, till exempel svår bröstsmärta eller andningssvårigheter, ring 112.</div><div class="result-links"><a class="button button-dark" href="tel:1177">Ring 1177 '+arrow+'</a><a class="button button-ghost" href="tel:112">Akut: ring 112 '+arrow+'</a></div><p class="guide-source">Läs hos <a href="https://www.1177.se/" target="_blank" rel="noopener noreferrer">1177 ↗<span class="sr-only">, ny flik</span></a>.</p>'+back('Tillbaka till mina val');
      }else if(state.screen==='result' && area){
        const title=state.area==='shoulder'?'Axelbedömning':'Naprapati: börja med en bedömning';
        const reason=state.area==='shoulder'?'När axeln är huvudproblemet kan du välja en riktad axelbedömning. Behandlaren avgör vad som behöver undersökas.':'Ett undersökningsbesök är en ingång när du behöver förstå besvären och få en plan. Du behöver inte välja behandlingsmetod i förväg.';
        const next=window.KanseiBooking[state.area==='shoulder'?'skuldra':'naprapati'];
        const articles={shoulder:'/blogg/ont-i-axeln-impingement-eller-nagot-annat/',knee:'/blogg/knaartros-vad-du-kan-gora/',back:'/blogg/ultraljud-eller-magnetkamera/'};
        content.innerHTML=step('03 / DITT NÄSTA STEG',3)+heading('Börja med att förstå besvären.')+`<span class="result-tag">${escapeHTML(area.label)}</span><p class="result-summary">${escapeHTML(pattern?.[1] || 'Jag vill börja med en bedömning.')}</p><div class="result-main"><span class="eyebrow">EN INGÅNG TILL KLINIKEN</span><h3>${escapeHTML(title)}</h3><p>${escapeHTML(reason)}</p><a class="button button-dark" data-measure="booking_click" data-placement="guide" href="${next.url}" target="_blank" rel="noopener noreferrer">${escapeHTML(next.label)} ${arrow}<span class="sr-only">, ny flik</span></a><small>${escapeHTML(next.price)} · Du kommer till rätt tjänst. Du väljer tid och bekräftar själv på Bokadirekt.</small></div><div class="result-details"><details><summary>Vad tittar ni på?</summary><p>${escapeHTML(area.focus)}</p></details><details><summary>Behöver jag ultraljud?</summary><p>${escapeHTML(area.imaging)}</p></details></div><div class="result-links">${routeLink(area.page,'Läs om besöket')}${articles[state.area]?routeLink(articles[state.area],'Läs mer i kunskapsbanken'):routeLink('/kunskapsbank/','Utforska våra guider')}</div>`+'<p class="guide-small">Detta är bokningsinformation, inte en medicinsk bedömning eller behandlingsrekommendation.</p>'+back('Ändra mina val');
      }else if(state.screen==='services'){
        const services=[['/naprapati/','Naprapati','Undersökning, behandling och uppföljning.'],['/ultraljud/','Muskuloskeletalt ultraljud','För en riktad frågeställning.'],['/skuldra/','Axelbedömning','När axeln är huvudproblemet.'],['/injektioner/','Injektionskonsultation','Bedömning före eventuell injektion.'],['/rehabilitering/','Rehab & uppföljning','Följ planen med din behandlare.']];
        content.innerHTML=step('VÄLJ DET DU SÖKER',1)+heading('Vet du redan? Gå direkt.')+'<p>Läs om besöket eller öppna Bokadirekt för att välja tjänst och tid.</p><div class="guide-choices">'+services.map(([path,title,text])=>`<a class="guide-choice" href="${path}" data-route="${path}"><span><b>${title}</b><small>${text}</small></span>${arrow}</a>`).join('')+'</div>'+back('Till bokningshjälpen');
      }else{resetState();return renderGuide();}
      prepareLinks(content);
      guide.scrollTop=0;
      if(guide.open)$('#guide-title',content)?.focus({preventScroll:true});
    }
    function start(opener,area=null,screen=null,initialPattern=null){resetState();if(area && areas[area]){state.area=area;state.screen='patterns';state.history=['areas'];}if(screen)state.screen=screen;renderGuide();openDialog(guide,opener);$('#guide-title',content)?.focus({preventScroll:true});if(initialPattern && area){const p=areas[area]?.patterns.find(p=>p[0]===initialPattern);if(p){state.pattern=p[0];move(p[4]?'care':'safety');}}}
    listen(content,'click',event=>{
      const b=event.target.closest('button');if(!b)return;
      if(b.hasAttribute('data-guide-area') && areas[b.dataset.guideArea]){state.area=b.dataset.guideArea;state.pattern=null;move('patterns');}
      else if(b.hasAttribute('data-pattern')){const p=areas[state.area]?.patterns.find(p=>p[0]===b.dataset.pattern);if(!p && b.dataset.pattern!=='unclear')return;state.pattern=b.dataset.pattern;move(p?.[4]?'care':'safety');}
      else if(b.hasAttribute('data-safety'))move(b.dataset.safety==='continue'?'result':'care');
      else if(b.hasAttribute('data-guide-back')){state.screen=state.history.pop() || 'areas';renderGuide();}
      else if(b.hasAttribute('data-reset')){resetState();renderGuide();}
      else if(b.hasAttribute('data-guide-services'))move('services');
      else if(b.hasAttribute('data-guide-care'))move('care');
    });
return {start, reset:resetState};
};
